window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5d0051e2a54f6d2c"]={"versions": [{"id": "FIG-5d0051e2a54f6d2c", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architekturdiagramm zur Veranschaulichung einer VFB-Kommunikationskette (Virtual Function Bus) auf Anwendungsebene der AUTOSAR Classic Platform. Das Diagramm modelliert einen funktionalen Signalpfad über mehrere Software-Komponenten hinweg, der als Referenzbeispiel für Timing-Anforderungen (Timing Requirement 1) dient.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Vier vertikal angeordnete AUTOSAR-Software-Komponenten (SW-C), jeweils mit Eingangsschnittstellen (Receiver-Ports, Dreiecke mit Spitze nach oben) und Ausgangsschnittstellen (Sender-Ports, Dreiecke mit Spitze nach unten), angebunden an den gemeinsamen roten Busbereich („Virtual Function Bus“):</p>\n<ul class=\"fig-list\">\n<li><strong>Accelerator Pedal</strong> (Typ: <code>Sensor Software Component</code>, symbolisiert durch ein Zeigerinstrument-Icon oben rechts) mit einem Eingangs-Port (gestrichelte Zuleitung) und einem Sender-Port.</li>\n<li><strong>Accelerator Pedal Voter</strong> (Typ: <code>Application Software Component</code>, symbolisiert durch ein Standard-Komponenten-Icon oben rechts) mit einem Receiver-Port und einem Sender-Port.</li>\n<li><strong>Throttle Controller</strong> (Typ: <code>Application Software Component</code>, Standard-Komponenten-Icon oben rechts) mit einem Receiver-Port und einem Sender-Port.</li>\n<li><strong>Throttle Actuator</strong> (Typ: <code>Actuator Software Component</code>, Zeigerinstrument-Icon oben rechts) mit einem Receiver-Port und einem Sender-Port (gestrichelte Weiterleitung).</li>\n<li><strong>Virtual Function Bus</strong>: Abstrakte Kommunikationsinfrastruktur, über die die VFB-Konnektoren geführt sind.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Signalfluss verläuft gerichtet von links nach rechts über den Virtual Function Bus:</p>\n<ol class=\"fig-list\">\n<li>Signalaufnahme über die Sensor-Komponente <code>Accelerator Pedal</code>.</li>\n<li>Weiterleitung vom Sender-Port von <code>Accelerator Pedal</code> über den VFB an den Receiver-Port von <code>Accelerator Pedal Voter</code>.</li>\n<li>Signalverarbeitung/Plausibilisierung in <code>Accelerator Pedal Voter</code> und Weiterleitung via VFB an den Receiver-Port von <code>Throttle Controller</code>.</li>\n<li>Berechnung der Stellgröße in <code>Throttle Controller</code> und Übertragung über den VFB an den Receiver-Port von <code>Throttle Actuator</code>.</li>\n<li>Ausgabe über den Aktor-Pfad (gestrichelt nach rechts).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine exemplarische VFB-Ereigniskette (<code>EventChain</code>) zur Spezifikation von Latenzzeiten und Timing-Vorgaben gemäß AUTOSAR TPS Timing Extensions. Für Entwickler verdeutlicht es die funktionale Dekomposition einer Steuerungsfunktion in Sensor-, Anwendungs- und Aktor-SW-Cs sowie die Entkopplung der Komponenten-Ports über VFB-Verbindungen vor dem finalen ECU-Mapping.</p>"}, {"id": "FIG-22e44005c8ea5599", "releases": ["R19-11", "R20-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architekturdiagramm zur Veranschaulichung einer VFB-Kommunikationskette (Virtual Functional Bus) auf Anwendungsebene der AUTOSAR Classic Platform. Das Diagramm modelliert einen funktionalen Signalpfad über mehrere Software-Komponenten hinweg, der als Referenzbeispiel für Timing-Anforderungen (Timing Requirement 1) dient.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Vier vertikal angeordnete AUTOSAR-Software-Komponenten (SW-C), jeweils mit Eingangsschnittstellen (Receiver-Ports, Dreiecke mit Spitze nach oben) und Ausgangsschnittstellen (Sender-Ports, Dreiecke mit Spitze nach unten), angebunden an den gemeinsamen roten Busbereich („Virtual Functional Bus“):</p>\n<ul class=\"fig-list\">\n<li><strong>Accelerator Pedal</strong> (Typ: <code>Sensor Software Component</code>, symbolisiert durch ein Zeigerinstrument-Icon oben rechts) mit einem Eingangs-Port (gestrichelte Zuleitung) und einem Sender-Port.</li>\n<li><strong>Accelerator Pedal Voter</strong> (Typ: <code>Application Software Component</code>, symbolisiert durch ein Standard-Komponenten-Icon oben rechts) mit einem Receiver-Port und einem Sender-Port.</li>\n<li><strong>Throttle Controller</strong> (Typ: <code>Application Software Component</code>, Standard-Komponenten-Icon oben rechts) mit einem Receiver-Port und einem Sender-Port.</li>\n<li><strong>Throttle Actuator</strong> (Typ: <code>Actuator Software Component</code>, Zeigerinstrument-Icon oben rechts) mit einem Receiver-Port und einem Sender-Port (gestrichelte Weiterleitung).</li>\n<li><strong>Virtual Functional Bus</strong>: Abstrakte Kommunikationsinfrastruktur, über die die VFB-Konnektoren geführt sind.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Signalfluss verläuft gerichtet von links nach rechts über den Virtual Functional Bus:</p>\n<ol class=\"fig-list\">\n<li>Signalaufnahme über die Sensor-Komponente <code>Accelerator Pedal</code>.</li>\n<li>Weiterleitung vom Sender-Port von <code>Accelerator Pedal</code> über den Bus an den Receiver-Port von <code>Accelerator Pedal Voter</code>.</li>\n<li>Signalverarbeitung/Plausibilisierung in <code>Accelerator Pedal Voter</code> und Weiterleitung via Bus an den Receiver-Port von <code>Throttle Controller</code>.</li>\n<li>Berechnung der Stellgröße in <code>Throttle Controller</code> und Übertragung über den Bus an den Receiver-Port von <code>Throttle Actuator</code>.</li>\n<li>Ausgabe über den Aktor-Pfad (gestrichelt nach rechts).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine exemplarische VFB-Ereigniskette (<code>EventChain</code>) zur Spezifikation von Latenzzeiten und Timing-Vorgaben gemäß AUTOSAR TPS Timing Extensions. Für Entwickler verdeutlicht es die funktionale Dekomposition einer Steuerungsfunktion in Sensor-, Anwendungs- und Aktor-SW-Cs sowie die Entkopplung der Komponenten-Ports über VFB-Verbindungen vor dem finalen ECU-Mapping.</p>"}], "trans": [{"from": "FIG-5d0051e2a54f6d2c", "to": "FIG-22e44005c8ea5599", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Beschriftung des Kommunikationsbusses: „Virtual Function Bus“ wurde zu „Virtual Functional Bus“ umbenannt.</li>\n</ul>"}]};
